# Generated by manage.py generate_test_cases.
import json
from urllib.parse import urlsplit

from bs4 import BeautifulSoup
from django.contrib.contenttypes.models import ContentType
from django.http import HttpResponse, QueryDict
from django.urls import reverse

from bloomerp.models.document_templates.document_template import DocumentTemplate
from bloomerp.tests.base import (
    BloomerpDetailViewTestCase,
    ExpectedResult,
    ModelRequestScenario,
    RequestScenario,
)
from bloomerp.tokens import REQUEST_TOKEN_QUERY_KEYS, get_token


class TestDocumentTemplateListDetailView(BloomerpDetailViewTestCase):
    """Tests class `DocumentTemplateListDetailView` from `bloomerp/views/generic/detail/document_templates.py`."""

    view_name = "document_templates"
    model = None

    def get_test_scenarios(self) -> list[RequestScenario]:
        """Check the loader and its record-specific generation arguments."""
        record = self.CustomerModel.objects.create(
            first_name="Document", last_name="Owner", age=30
        )
        self.record_id = record.pk
        self.document_template = DocumentTemplate.objects.create(name="Document template")
        self.document_template.content_types.add(ContentType.objects.get_for_model(record))
        return [
            ModelRequestScenario(
                name="Document templates load with the current record's generation URL",
                user=self.admin_user,
                model=self.CustomerModel,
                view_kwargs={"pk": record.pk},
                expected=ExpectedResult(response_validators=self.has_document_templates_loader),
            ),
        ]

    def has_document_templates_loader(self, response: HttpResponse) -> bool:
        """Verify item activation opens the registered action for the detail record."""
        template_type_id = ContentType.objects.get_for_model(DocumentTemplate).pk
        record_type_id = str(ContentType.objects.get_for_model(self.CustomerModel).pk)
        endpoint = reverse("components_dataview", kwargs={"content_type_id": template_type_id})
        document = BeautifulSoup(response.content, "html.parser")
        loader = document.select_one(f'[hx-trigger="load"][hx-get^="{endpoint}"]')
        self.assertIsNotNone(loader)
        query = QueryDict(urlsplit(loader["hx-get"]).query)
        self.assertFalse(REQUEST_TOKEN_QUERY_KEYS.intersection(query))
        rendered = self.client.get(loader["hx-get"], headers={"HX-Request": "true", **json.loads(loader["hx-headers"])})
        token = get_token(rendered.wsgi_request).dataviews[DocumentTemplate]
        self.assertEqual(token.dataview.default_filters["content_types"], record_type_id)
        self.assertContains(rendered, 'data-item-click="action"')
        self.assertNotContains(rendered, 'data-dataview-create-button="true"')
        dataview = BeautifulSoup(rendered.content, "html.parser")
        action = dataview.select_one('button[data-object-action-id="generate-document"]')
        self.assertIsNotNone(action)
        self.assertEqual(action["bloomerp-open-modal"], "bloomerp-general-use-modal")
        generate_url = urlsplit(action["hx-get"])
        self.assertEqual(
            generate_url.path,
            reverse("components_generate_document_template", kwargs={"id": self.document_template.pk}),
        )
        self.assertEqual(QueryDict(generate_url.query).dict(), {
            "content_type_id": record_type_id,
            "object_id": str(self.record_id),
        })
        return True
